INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 17, 'theory', 'Квиз: архитектура oVirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 0, 'Что произойдёт с уже работающими виртуальными машинами, если менеджер oVirt временно недоступен?', '["Все машины будут остановлены хостами", "Они продолжат работать, но управлять ими нельзя", "Они автоматически мигрируют на резервный менеджер", "Они перейдут в режим только для чтения"]', 1, 'Машины запускают и ведут хосты через libvirt и QEMU. Менеджер лишь отдаёт приказы и хранит конфигурацию, поэтому его сбой лишает управления, но не гасит машины.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 1, 'Каков правильный порядок вложенности объектов в oVirt, от большего к меньшему?', '["Кластер, центр данных, хост, ВМ", "Центр данных, кластер, хост, ВМ", "Центр данных, хост, кластер, ВМ", "Хост, кластер, центр данных, ВМ"]', 1, 'Центр данных объединяет общие хранилища и сети, внутри него кластеры, внутри кластеров хосты, а машина привязана к кластеру и запущена на хосте.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 2, 'Какую роль играет VDSM?', '["Хранит базу данных менеджера", "Принимает команды менеджера на хосте и вызывает libvirt", "Отображает веб-портал администратора", "Выбирает хост для запуска машины"]', 1, 'VDSM — демон на хосте: он исполняет приказы менеджера через libvirt, следит за хранилищем и сетью и докладывает состояние. Выбирает хост планировщик менеджера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 3, 'Чем hosted engine отличается от standalone?', '["Он не использует базу данных", "Менеджер работает виртуальной машиной на хостах, которыми управляет", "Он управляет только одним хостом", "У него нет REST-интерфейса"]', 1, 'В hosted engine машина менеджера лежит на общем хранилище, а специальные службы перезапускают её на другом хосте при отказе. База и API остаются теми же.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 4, 'Что верно про версию совместимости кластера?', '["Её можно свободно понижать и повышать", "Её можно поднять, когда все хосты и менеджер её поддерживают", "Она определяет только цвет значка в портале", "Она всегда равна версии ядра хоста"]', 1, 'Версия совместимости включает набор возможностей, и повышается она только после обновления всех участников. Вернуть прежнюю версию нельзя.');
